// spillFileJobRecord mirrors the FileJob fields required to replay results through formatters.
type spillFileJobRecord struct {
    Language           string
    PossibleLanguages  []string
    Filename           string
    Extension          string
    Location           string
    Symlocation        string
    Bytes              int64
    Lines              int64
    Code               int64
    Comment            int64
    Blank              int64
    Complexity         int64
    WeightedComplexity float64
    Binary             bool
    Minified           bool
    Generated          bool
    EndPoint           int
    Uloc               int
    LineLength         []int
}

func fileJobToSpillRecord(j *FileJob) spillFileJobRecord {...}
func (r *spillFileJobRecord) toFileJob() *FileJob {...}

type boundedFileStore struct {
    dir        string
    maxInMem   int
    buffer     []*FileJob
    spillFiles []string
    spills     int
    peak       int
    count      int64
}

func newBoundedFileStore(dir string, maxInMem int) *boundedFileStore {
    return &boundedFileStore{dir: dir, maxInMem: maxInMem}
}

// add stages a job in memory, spilling the staged buffer to disk whenever it is full.
func (s *boundedFileStore) add(job *FileJob) error {
    if len(s.buffer) >= s.maxInMem {
        if err := s.spill(); err != nil { return err }
    }
    s.buffer = append(s.buffer, job)
    if len(s.buffer) > s.peak { s.peak = len(s.buffer) }
    s.count++
    return nil
}

func (s *boundedFileStore) spill() error {
    if len(s.buffer) == 0 { return nil }
    name := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-memory-spill-%06d.jsonl", s.spills))
    f, err := os.OpenFile(name, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
    if err != nil { return err }
    w := bufio.NewWriter(f)  // efficient
    enc := jsoniter.ConfigCompatibleWithStandardLibrary
    for _, j := range s.buffer {
        b, err := enc.Marshal(fileJobToSpillRecord(j))
        if err != nil { f.Close(); return err }
        w.Write(b); w.WriteByte('\n')
    }
    w.Flush(); f.Close()
    s.spillFiles = append(s.spillFiles, name)
    s.spills++
    s.buffer = s.buffer[:0]
    return nil
}

// close spills any remaining staged records so every record lives on disk for replay.
func (s *boundedFileStore) close() error { return s.spill() }

// replay streams every stored record in arrival order over the returned channel.
func (s *boundedFileStore) replay() chan *FileJob {
    out := make(chan *FileJob)
    go func() {
        defer close(out)
        for _, name := range s.spillFiles {
            f, err := os.Open(name)
            if err != nil { printError(...); continue? or... }
            dec := jsoniter...NewDecoder(f)  — hmm, jsoniter decoder: json.NewDecoder(f) with jsoniter config: jsoniter.ConfigCompatibleWithStandardLibrary.NewDecoder(f)
            for {
                var rec spillFileJobRecord
                err := dec.Decode(&rec)
                if err == io.EOF { break }
                if err != nil { printError; break }
                out <- rec.toFileJob()
            }
            f.Close()
        }
    }()
    return out
}
