// configureBoundedMemory validates the bounded memory flags and prepares the spill
// directory, creating it when it does not exist. Invalid combinations are fatal.
func configureBoundedMemory() {
	if !BoundedMemory {
		return
	}

	if strings.TrimSpace(BoundedMemoryDir) == "" {
		fmt.Println("--bounded-memory-dir is required when --bounded-memory is enabled")
		os.Exit(1)
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		fmt.Println("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
		os.Exit(1)
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		fmt.Println("bounded memory spill directory could not be created: " + err.Error())
		os.Exit(1)
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		fmt.Println("bounded memory spill directory could not be resolved: " + err.Error())
		os.Exit(1)
	}

	boundedMemoryAbsDir = abs
	boundedMemorySpills = 0
	boundedMemoryPeakInMemoryFiles = 0

	printDebugF("Bounded Memory Dir: %s", boundedMemoryAbsDir)
	printDebugF("Bounded Memory Max In Memory Files: %d", BoundedMemoryMaxInMemoryFiles)
}

// isWithinBoundedMemoryDir reports if path sits inside the bounded memory spill
// directory so spill files are excluded from counting
func isWithinBoundedMemoryDir(path string) bool {
	if boundedMemoryAbsDir == "" {
		return false
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		return false
	}

	return abs == boundedMemoryAbsDir || strings.HasPrefix(abs, boundedMemoryAbsDir+string(os.PathSeparator))
}

