import json, sys
def canon(path):
    with open(path) as f:
        lines = f.read().split("\n")
    j1 = json.loads(lines[0]); j2 = json.loads(lines[1])
    csv = "\n".join(lines[2:])
    for doc in (j1, j2):
        langs = doc if isinstance(doc, list) else doc["languageSummary"]
        for l in langs:
            if l.get("Files"):
                l["Files"].sort(key=lambda x: x["Location"])
                for fobj in l["Files"]:
                    if fobj.get("PossibleLanguages"):
                        fobj["PossibleLanguages"] = sorted(fobj["PossibleLanguages"])
    return json.dumps(j1, sort_keys=True), json.dumps(j2, sort_keys=True), csv
a = canon(sys.argv[1]); b = canon(sys.argv[2])
