func TestBoundedMemoryStatsLineFormat(t *testing.T) {
	line := boundedMemoryStatsLine(7, 1)

	if !strings.HasPrefix(line, "bounded-memory:") {
		t.Error("expected the stats line to begin with bounded-memory:")
	}

	fields := strings.Fields(strings.TrimPrefix(line, "bounded-memory: "))
	if len(fields) != 2 {
		t.Fatalf("expected two fields in the stats line got %q", line)
	}

	if !strings.HasPrefix(fields[0], "spills=") || !strings.HasPrefix(fields[1], "peak_in_memory_files=") {
		t.Fatalf("expected spills and peak_in_memory_files fields got %q", line)
	}

	if _, err := strconv.Atoi(strings.TrimPrefix(fields[0], "spills=")); err != nil {
		t.Error("expected spills to be an integer field")
	}
	if _, err := strconv.Atoi(strings.TrimPrefix(fields[1], "peak_in_memory_files=")); err != nil {
		t.Error("expected peak_in_memory_files to be an integer field")
	}
}

